#include <iostream>

constexpr int square(int n) { return n * n; }
consteval int checkedWidth(int n)
{
    if (n < 1 || n > 8) throw "width outside lesson range";
    return n;
}
constinit int sessions{2};

int main()
{
    constexpr int width{checkedWidth(4)};
    constexpr int area{square(width)};
    static_assert(area == 16);
    ++sessions;
    std::cout << area << ' ' << sessions << '\n';
}
